# -*- coding: utf-8 -*-


# This file was *autogenerated* from the file solve_v2.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_0 = Integer(0); _sage_const_256 = Integer(256); _sage_const_75 = Integer(75); _sage_const_10 = Integer(10); _sage_const_16 = Integer(16)
from sage.all import *
import re
from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad
from hashlib import sha256

print("[*] Loading ciphertext.txt ...")

raw = open("ciphertext.txt").read().strip()

# ============================================================
# PARSE (z, w)
# ============================================================

m = re.search(r"\((.*)\)", raw, flags=re.DOTALL)
inside = m.group(_sage_const_1 ).strip()

depth = _sage_const_0 
split_pos = -_sage_const_1 
for i,ch in enumerate(inside):
    if ch == '(':
        depth += _sage_const_1 
    elif ch == ')':
        depth -= _sage_const_1 
    elif ch == ',' and depth == _sage_const_0 :
        split_pos = i
        break

z_str = inside[:split_pos].strip()
w_str = inside[split_pos+_sage_const_1 :].strip()

# Convert ^ → **
def fix_power(s):
    return re.sub(r"\^(\d+)", r"**\1", s)

z_str = fix_power(z_str)
w_str = fix_power(w_str)

# ============================================================
# PARSE ciphertext hex
# ============================================================

m2 = re.search(r"([0-9a-fA-F]{40,})$", raw)
ct_hex = m2.group(_sage_const_1 ).strip()

print("[+] Ciphertext hex:", ct_hex)

# ============================================================
# BUILD polynomial ring
# ============================================================

n = _sage_const_256 

Rt = PolynomialRing(ZZ, names=('t',)); (t,) = Rt._first_ngens(1)
P = QuotientRing(Rt, t**n + _sage_const_1 , names=('a',)); (a,) = P._first_ngens(1)

z = eval(z_str, {"a": a})
w = eval(w_str, {"a": a})

print("[+] Parsed z, w in Sage.")

# ============================================================
# CORRECT coeff extractor
# ============================================================

def coeffs(poly):
    rep = poly.lift()        # in ZZ[t]
    rep = rep % (t**n + _sage_const_1 )   # reduce correctly
    return [ZZ(rep[i]) for i in range(n)]

zv = coeffs(z)
wv = coeffs(w)

print("[+] Coeff extraction OK.")

# ============================================================
# BUILD linear system A*e = b  (rows 75..255)
# ============================================================

rows = list(range(_sage_const_75 ,_sage_const_256 ))

def mult_column(j):
    tmp = [_sage_const_0 ]*n
    for i in range(n):
        if wv[i] == _sage_const_0 : continue
        idx = i + j
        if idx >= n:
            tmp[idx-n] -= wv[i]
        else:
            tmp[idx] += wv[i]
    return tmp

A = Matrix(QQ, len(rows), n)
for col in range(n):
    colv = mult_column(col)
    for r_i,k in enumerate(rows):
        A[r_i,col] = colv[k]

b = vector(QQ, [zv[k] for k in rows])

print("[*] Solving A*e = b ...")

e = A.solve_right(b)
e_int = [ZZ(round(v)) for v in e]

print("[+] First 10 coefficients:", e_int[:_sage_const_10 ])

# ============================================================
# RECONSTRUCT KEY
# ============================================================

key_poly = sum(e_int[i]*a**i for i in range(n))

print("[+] Key reconstructed.")

# ============================================================
# AES decrypt
# ============================================================

key_aes = sha256(str(key_poly).encode()).digest()[:_sage_const_16 ]
cipher = AES.new(key_aes, AES.MODE_ECB)
pt_raw = cipher.decrypt(bytes.fromhex(ct_hex))

try:
    pt = unpad(pt_raw, _sage_const_16 )
except:
    pt = pt_raw

print("\n================ FLAG ================\n")
print(pt)
print("\n======================================\n")

